mapper.select:
SELECT COUNT(*) FROM reservation
WHERE equipment_id = #{equipmentId}
  AND deleted = 0
  AND status IN (0, 1)
  AND start_time < #{endTime}
  AND end_time > #{startTime}
AND id != #{excludeId}

SELECT r.* FROM reservation r
JOIN equipment e ON e.id = r.equipment_id
JOIN lab l ON l.id = e.lab_id
WHERE r.deleted = 0
AND r.student_id = #{studentId}
AND l.admin_id = #{managerId} AND l.deleted = 0
AND r.equipment_id = #{query.equipmentId}
AND e.lab_id = #{query.labId}
AND r.status = #{query.status}
ORDER BY r.apply_time DESC, r.id DESC

SELECT id FROM reservation
WHERE deleted = 0 AND status = 0 AND start_time <= #{now} AND id > #{afterId}
ORDER BY id LIMIT #{limit}

SELECT id FROM reservation
WHERE deleted = 0 AND status = 1 AND sign_in_time IS NULL
  AND start_time <= #{deadline} AND id > #{afterId}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE usage_log
SET end_time = (SELECT r.end_time FROM reservation r WHERE r.id = usage_log.reservation_id),
    update_time = #{now}
WHERE deleted = 0 AND end_time IS NULL AND reservation_id IN (
    SELECT r.id FROM reservation r WHERE r.equipment_id = #{equipmentId}
      AND r.deleted = 0 AND r.status = 1 AND r.sign_in_time IS NOT NULL
      AND r.end_time <= #{now}
)
